// Seite zeigt nur an, der Knopf startet neue Lieferungen
// Zwei Adressen mit je eigener Passwortabfrage: Svetlana und Legal (Sabrina)
const knopf = $('Jetzt prüfen gedrückt').isExecuted || $('Jetzt prüfen gedrückt (Legal)').isExecuted;
const legal = $('Seite aufgerufen (Legal)').isExecuted || $('Jetzt prüfen gedrückt (Legal)').isExecuted;
return [{ json: { art: knopf ? 'starten' : 'auflisten', knopf, wer: legal ? 'Übersicht Legal' : 'Übersicht' } }];

// Setzt die Daten in die Seite ein. Vorlage: seite.html (BC3-82) im Ablageordner.
// "<" wird im JSON maskiert, damit kein Text aus der Datenbank den Skriptblock beenden kann.
const eingang = $('BC3-01 aufrufen').first().json;
const zeilen = name => $(name).all().map(i => i.json).filter(z => Object.keys(z).length);
const gate2 = {};
for (const z of zeilen('Gate-2-Links holen')) gate2[z.lauf_id] = '/webhook/__PFAD_GATE2__?lauf=' + encodeURIComponent(z.lauf_id) + '&t=' + z.token;
const daten = JSON.stringify({
  stand: new Date().toISOString(),
  eingang: eingang.error ? { fehler: eingang.error.message || 'BC3-01 gescheitert', liste: [] } : eingang,
  laeufe: zeilen('Läufe holen'),
  freigaben: zeilen('Entscheidungen holen'),
  fehler: zeilen('Fehler holen'),
  gate2,
  pruefstand: zeilen('Prüfstand holen')[0] || null,
}).replace(/</g, '\u003c');

const SEITE = "<!doctype html>
<html lang="de">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<meta name="referrer" content="no-referrer">
<title>BC3 · Übersicht</title>
<!--
  BC3 · Übersicht, ausgeliefert von BC3-82 (n8n). Vorlage für "Seite bauen".
  BC3-82 setzt die Daten in den Skriptblock "daten" ein: Lieferungen von BC2 (über BC3-01),
  laeufe, freigaben, fehler und die Links offener Gate-2-Seiten.
  "Jetzt prüfen" schickt einen POST an dieselbe Adresse, BC3-82 ruft dann BC3-01 mit "starten" auf.
-->
<style>
:root{
  --navy:#1F3A5F; --accent:#3B6EA5; --bg:#f4f6f9; --ink:#1f2933; --muted:#6b7280;
  --line:#dde2e8; --ok:#1f9d57; --warn:#c0392b; --amber:#d98c1f; --chip:#eef2f7;
}
*{box-sizing:border-box}
body{margin:0;font-family:"Segoe UI",Calibri,Arial,sans-serif;color:var(--ink);background:var(--bg);
     font-size:15px;line-height:1.45}
code{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:12.5px;background:var(--chip);
     padding:1px 5px;border-radius:4px}
a{color:var(--accent)}
.topbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;background:var(--navy);color:#fff;padding:12px 20px}
.topbar b{font-size:17px}
.topbar .sub{opacity:.85;font-size:14px}
.topbar .rechts{margin-left:auto;display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.knopf{background:#fff;color:var(--navy);border:none;border-radius:7px;padding:7px 12px;font-family:inherit;
       font-size:14px;font-weight:600;cursor:pointer}
.knopf:disabled{opacity:.6;cursor:wait}
.meldung{font-size:13px;opacity:.9}
/* Seit 23.10.2026: Seitenleiste links, rechts immer nur ein Bereich */
.rahmen{display:grid;grid-template-columns:200px minmax(0,1fr);gap:16px;max-width:1200px;margin:0 auto;padding:16px}
nav{position:sticky;top:12px;align-self:start;display:flex;flex-direction:column;gap:2px}
nav a{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 10px;border-radius:8px;
      color:var(--ink);text-decoration:none;font-size:14px;border:1px solid transparent}
nav a:hover{background:#fff}
nav a.aktiv{background:#fff;border-color:var(--line);color:var(--navy);font-weight:600}
nav .tag{font-weight:400}
main{min-width:0}
.mehr{margin-top:6px}
section{background:#fff;border:1px solid var(--line);border-radius:10px;padding:16px 18px;margin:0 0 14px}
h2{font-size:16px;margin:0 0 10px;color:var(--navy)}
.zahlen{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin:0 0 14px}
.zahl{background:#fff;border:1px solid var(--line);border-radius:10px;padding:8px 12px}
.zahl .wert{font-size:20px;font-weight:600;color:var(--navy)}
.zahl .was{font-size:13px;color:var(--muted)}
