.tag{display:inline-block;padding:1px 8px;border-radius:999px;font-size:12px;background:var(--chip);color:var(--navy);white-space:nowrap}
.tag.gruen{background:#e7f6ee;color:var(--ok)} .tag.rot{background:#fbe9e7;color:var(--warn)}
.tag.gelb{background:#fdf2e1;color:#8a5a00} .tag.grau{background:#f1f2f4;color:var(--muted)}
.leiste{display:flex;gap:3px;align-items:center}
.leiste i{display:block;width:16px;height:8px;border-radius:2px;background:var(--line)}
.leiste i.ja{background:var(--accent)} .leiste i.jetzt{background:var(--amber)}
.leiste i.ab{background:var(--warn)} .leiste i.frei{background:var(--ok)} .leiste i.nach{background:var(--amber)}
.klein{font-size:12.5px;color:var(--muted)}
.hinweis{color:var(--muted);font-size:13.5px;margin:4px 0}
details summary{cursor:pointer;color:var(--navy);font-weight:600;padding:6px 0}
.leer{color:var(--muted);font-size:14px}
.grenzen{border-left:4px solid var(--accent)}
.grenzen ul{margin:0;padding-left:20px}
.grenzen li{margin:0 0 6px}
@media (max-width:700px){
  .rahmen{grid-template-columns:1fr;padding:10px;gap:10px}
  nav{position:static;flex-direction:row;overflow-x:auto;gap:4px;padding-bottom:4px}
  nav a{white-space:nowrap;padding:6px 10px}
  section{padding:14px}
  .topbar{padding:10px 14px}
  .topbar .rechts{margin-left:0;width:100%}
  .weg-mobil{display:none}
}
</style>
</head>
<body>
<div class="topbar">
  <b>BC3 · Übersicht</b><span class="sub">Lieferungen von BC2, Läufe, Gate 2, Weitergabe an BC4</span>
  <span class="rechts"><span class="meldung" id="meldung"></span><button class="knopf" id="pruefen">Jetzt prüfen</button></span>
</div>
<div class="rahmen"><nav id="navi"></nav><main id="seite"></main></div>
<script id="daten" type="application/json">__DATEN__</script>
<script>
const D = JSON.parse(document.getElementById('daten').textContent);
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const zeit = v => v ? new Date(v).toLocaleString('de-DE', { dateStyle: 'short', timeStyle: 'short' }) : '–';
const tag = v => v ? new Date(v).toLocaleDateString('de-DE') : '–';
const dauer = (a, b) => {
  if (!a || !b) return '–';
  const m = Math.round((new Date(b) - new Date(a)) / 60000);
  return m < 60 ? m + ' min' : m < 2880 ? (m / 60).toFixed(1).replace('.', ',') + ' h' : Math.round(m / 1440) + ' Tage';
};
const konzept = p => (String(p || '').match(/konzept_([^/]+)[.]json$/) || [])[1] || '–';
const kurz = s => String(s || '').length > 160 ? String(s).slice(0, 157) + ' …' : String(s || '');

const SCHRITTE = ['BC3-10', 'BC3-15', 'BC3-20', 'BC3-30', 'BC3-40', 'BC3-50', 'BC3-70', 'Gate 2', 'BC3-80'];
const STAND = {
  laeuft: ['läuft', ''], wartet_gate2: ['wartet auf Gate 2', 'gelb'], freigegeben: ['freigegeben', 'gruen'],
  nachbessern: ['nachbessern', 'gelb'], abgelehnt: ['abgelehnt', 'rot'], abgebrochen: ['abgebrochen', 'rot'],
};
const EINGANG = {
  neu: ['neu, startet beim nächsten Prüfen', 'gelb'], bekannt: ['bearbeitet', 'gruen'],
  nicht_freigegeben: ['Gate 1 nicht freigegeben', 'grau'], ohne_gate1: ['ohne Gate 1', 'grau'],
  ohne_priorisierung: ['ohne Priorisierung', 'grau'], priorisierung_nicht_lesbar: ['Priorisierung nicht lesbar', 'rot'],
};
const GATE1 = { approved: 'freigegeben', pending: 'offen', rejected: 'abgelehnt' };

// Seit 22.10.2026 (Expertenrunde Gate 2, Schritt 4): eine Zeile je Schritt der Laufleiste.
// Quelle ist bc3-engineering-architect/ablauf-slicer.md im Team-Repo; ändert sie sich, diese Liste mit anpassen.
const ABLAUF = [
  ['BC3-10', 'Konzept einlesen', 'holt das Konzept von BC2 aus GitHub und prüft den Eingang', 'ohne KI'],
  ['BC3-15', 'Plan festlegen', 'feste Regeln R1 bis R6 legen fest, was läuft; ein Ratgeber meldet nur Auffälligkeiten', 'KI nur als Ratgeber'],
  ['BC3-20', 'Stories schneiden', 'je Potenzial ein Epic mit Stories und Akzeptanzkriterien', 'KI'],
  ['BC3-30', 'Compliance prüfen', 'Ampel, Risikoklasse nach KI-Verordnung, Pflichten mit Adressat', 'KI'],
  ['BC3-40', 'Tickets bauen und prüfen', 'tickets.json und compliance-audit.json gegen den Vertrag 3.5, bricht ab, wenn etwas nicht passt', 'ohne KI'],
  ['BC3-50', 'Architektur', 'Bauplan: architecture.md und blueprint.json', 'ohne KI'],
  ['BC3-70', 'Ausliefern', 'offene Punkte sammeln, Dateien in Drive unter _vorschau ablegen', 'ohne KI'],
  ['Gate 2', 'Entscheidung', 'fünf maschinelle Prüfpunkte, Link per Telegram; ein Mensch entscheidet auf der Gate-2-Seite, Frist 7 Tage', 'Mensch'],
  ['BC3-80', 'Freigabe ausführen', 'Entscheidung in freigaben; bei Freigabe im Modus echt Pull Request an BC4', 'ohne KI'],
];

function ablauf() {
  return '<details><summary>So läuft ein Lauf</summary><div class="tabelle"><table>'
    + '<tr><th>Schritt</th><th>Was passiert</th><th class="weg-mobil">KI</th></tr>'
    + ABLAUF.map(([nr, name, was, ki]) => '<tr><td><b>' + esc(nr) + '</b><div class="klein">' + esc(name) + '</div></td><td>'
      + esc(was) + '</td><td class="weg-mobil">' + esc(ki) + '</td></tr>').join('')
    + '</table></div><p class="hinweis">Gestartet wird ein Lauf von BC3-01, alle 15 Minuten oder über „Jetzt prüfen“. '
    + 'Nach jedem Schritt steht der Stand in der Tabelle laeufe, Abbrüche stehen unten unter Fehler. '
    + 'Bild und Einzelheiten: <a href="https://github.com/pg-coe-kmu/coe-factory/blob/main/bc3-engineering-architect/ablauf-slicer.md">Ablauf des Slicers</a> im Team-Repo (Stand 23.10.2026).</p></details>';
}

// Abbrüche tragen den langen Stufennamen („BC3-10 Konzept einlesen“), daher über den Anfang vergleichen
const schrittNr = s => SCHRITTE.findIndex(x => s === x || String(s || '').startsWith(x + ' '));

function leiste(l) {
  const ende = ['freigegeben', 'nachbessern', 'abgelehnt'].includes(l.status);
  let bis = schrittNr(l.letzter_schritt);
  if (l.status === 'wartet_gate2') bis = SCHRITTE.indexOf('Gate 2');
  if (ende) bis = SCHRITTE.length;
  const ab = l.status === 'abgebrochen' ? schrittNr(l.abbruch_stufe) : -1;
  return '<span class="leiste" title="' + esc(SCHRITTE.join(' · ')) + '">' + SCHRITTE.map((s, i) => {
    let k = '';
    if (ab >= 0 && i === ab) k = 'ab';
    else if (s === 'Gate 2' && ende) k = { freigegeben: 'frei', nachbessern: 'nach', abgelehnt: 'ab' }[l.status];
    else if (i < bis || (ab >= 0 && i < ab)) k = 'ja';
    else if (i === bis && ['laeuft', 'wartet_gate2'].includes(l.status)) k = 'jetzt';
    return '<i class="' + k + '" title="' + esc(s) + '"></i>';
  }).join('') + '</span>';
}

function standTag(s) {
  const [text, farbe] = STAND[s] || [s || '–', 'grau'];
  return '<span class="tag ' + farbe + '">' + esc(text) + '</span>';
}

function laufZeile(l) {
  const link = D.gate2[l.lauf_id];
  const umfang = l.anzahl_epics != null ? l.anzahl_epics + ' / ' + (l.anzahl_stories ?? '–') : '–';
  const grund = l.status === 'abgebrochen'
    ? '<div class="klein">' + esc(l.abbruch_stufe || '') + ': ' + esc(kurz(l.abbruch_ursache)) + '</div>' : '';
  return '<tr><td>' + esc(l.lauf_id) + '<div class="klein">' + esc(l.modus || '') + '</div></td>'
    + '<td>' + esc(konzept(l.konzept_pfad)) + '<div class="klein">' + esc(l.use_case || '') + '</div></td>'
    + '<td>' + zeit(l.gestartet_am) + '</td>'
    + '<td class="weg-mobil">' + dauer(l.gestartet_am, l.beendet_am) + '</td>'
    + '<td>' + leiste(l) + '</td>'
    + '<td>' + standTag(l.status) + (link ? ' <a href="' + esc(link) + '">zur Gate-2-Seite</a>' : '') + grund + '</td>'
    + '<td class="weg-mobil">' + umfang + '</td></tr>';
}

const KOPF_LAEUFE = '<tr><th>Lauf</th><th>Konzept</th><th>Start</th><th class="weg-mobil">Dauer</th>'
  + '<th>Schritte</th><th>Stand</th><th class="weg-mobil">Epics / Stories</th></tr>';

// Seit 23.10.2026: eine Tabelle zeigt die ersten n Zeilen, der Rest klappt auf
function liste(zeilen, kopf, zeile, n, leer) {
  if (!zeilen.length) return '<p class="leer">' + leer + '</p>';
  const tab = z => '<div class="tabelle"><table>' + kopf + z.map(zeile).join('') + '</table></div>';
  return tab(zeilen.slice(0, n))
    + (zeilen.length > n ? '<details class="mehr"><summary>alle anzeigen (' + (zeilen.length - n) + ' weitere)</summary>'
      + tab(zeilen.slice(n)) + '</details>' : '');
}

function zeichnen() {
  const laeufe = D.laeufe, echt = laeufe.filter(l => l.modus === 'echt'), test = laeufe.filter(l => l.modus !== 'echt');
  const modus = Object.fromEntries(laeufe.map(l => [l.lauf_id, l.modus]));
  const entsch = D.freigaben;
  const zaehl = w => entsch.filter(f => f.entscheidung === w).length;
  const wartet = laeufe.filter(l => l.status === 'wartet_gate2');
  const geliefert = echt.filter(l => l.status === 'freigegeben');
  const eingang = D.eingang.liste || [];
  const neu = eingang.filter(e => e.stand === 'neu');
  const ordner = new Set(eingang.map(e => e.ordner)).size;
  const B = {};

  // --- Start: Kennzahlen, was auf dich wartet, die letzten Läufe ---------
  B.start = '<div class="zahlen">'
    + '<div class="zahl"><div class="wert">' + ordner + '</div><div class="was">Lieferungen von BC2</div>'
    + '<div class="dazu">' + eingang.filter(e => e.gate1 === 'approved').length + ' Konzepte an Gate 1 freigegeben</div></div>'
    + '<div class="zahl"><div class="wert">' + laeufe.length + '</div><div class="was">Läufe</div>'
    + '<div class="dazu">' + echt.length + ' echt, ' + test.length + ' Test</div></div>'
    + '<div class="zahl"><div class="wert">' + entsch.length + '</div><div class="was">Entscheidungen an Gate 2</div>'
    + '<div class="dazu">' + zaehl('freigegeben') + ' frei, ' + zaehl('nachbessern') + ' nachbessern, ' + zaehl('abgelehnt') + ' abgelehnt</div></div>'
    + '<div class="zahl"><div class="wert">8 von 9</div><div class="was">Schritte ohne Mensch</div>'
    + '<div class="dazu">nur Gate 2 entscheidet ein Mensch</div></div>'
    + '<div class="zahl"><div class="wert">' + geliefert.length + '</div><div class="was">an BC4 weitergegeben</div>'
    + '<div class="dazu">' + laeufe.filter(l => l.status === 'abgebrochen').length + ' Läufe abgebrochen</div></div>'
    + '</div>'
    + (wartet.length
      ? '<section class="warten"><h2>Wartet auf deine Entscheidung</h2>'
        + wartet.map(l => '<div>' + esc(l.lauf_id) + ', ' + esc(konzept(l.konzept_pfad)) + ', seit ' + zeit(l.gestartet_am)
          + (D.gate2[l.lauf_id] ? ' · <a href="' + esc(D.gate2[l.lauf_id]) + '">zur Gate-2-Seite</a>' : ' · Frist abgelaufen') + '</div>').join('')
        + '</section>'
      : '<section><h2>Wartet auf deine Entscheidung</h2><p class="leer">Nichts. Kein Lauf steht an Gate 2.</p></section>')
    + (neu.length ? '<section class="warten"><h2>Neu von BC2</h2><p>' + neu.length + ' Konzept(e) starten beim nächsten Prüfen. '
      + '<a href="#bc2">ansehen</a></p></section>' : '')
    + '<section><h2>Letzte Läufe</h2>'
    + liste(laeufe.slice(0, 3), KOPF_LAEUFE, laufZeile, 3, 'Noch kein Lauf.')
    + '<p class="klein"><a href="#laeufe">alle Läufe</a></p></section>';

  // --- Von BC2 bekommen ----------------------------------------------------
  B.bc2 = '<section><h2>Von BC2 bekommen</h2>'
    + (D.eingang.fehler ? '<p class="hinweis">Lieferungen gerade nicht abrufbar: ' + esc(D.eingang.fehler) + '</p>' : '')
    + '<p class="hinweis">' + eingang.length + ' Konzepte, davon ' + neu.length + ' neu.</p>'
    + liste(eingang, '<tr><th>Lieferung</th><th>Konzept</th><th class="weg-mobil">übergeben</th><th>Gate 1</th><th>bei BC3</th></tr>',
      e => {
        const [text, farbe] = EINGANG[e.stand] || [e.stand, 'grau'];
        return '<tr><td>' + esc(e.ordner) + '</td><td>' + esc(konzept(e.pfad)) + '</td>'
          + '<td class="weg-mobil">' + tag(e.uebergeben_am) + '</td>'
          + '<td>' + esc(GATE1[e.gate1] || e.gate1 || '–') + (e.gate1_am ? '<div class="klein">' + tag(e.gate1_am) + '</div>' : '') + '</td>'
          + '<td><span class="tag ' + farbe + '">' + esc(text) + '</span>'
          + (e.lauf_id ? '<div class="klein">zuletzt ' + esc(e.lauf_id) + ', ' + esc((STAND[e.lauf_status] || [e.lauf_status])[0]) + '</div>' : '')
          + '</td></tr>';
      }, 5, 'Keine Lieferungen gefunden.')
    + '</section>';

  // --- Läufe ---------------------------------------------------------------
  B.laeufe = '<section><h2>Läufe</h2>'
    + '<p class="hinweis">Schritte: ' + SCHRITTE.join(' · ') + '. Dauer vom Start bis zur Entscheidung an Gate 2.</p>'
    + ablauf()
    + '<h2 style="margin-top:12px">Echte Läufe</h2>'
    + liste(echt, KOPF_LAEUFE, laufZeile, 5, 'Noch kein echter Lauf.')
    + (test.length ? '<details class="mehr"><summary>Testläufe (' + test.length + ')</summary>'
      + liste(test, KOPF_LAEUFE, laufZeile, 10, '') + '</details>' : '')
    + '</section>';

  // --- Gate 2 --------------------------------------------------------------
  const entschZeile = f => '<tr><td>' + zeit(f.zeitpunkt) + '</td><td>' + esc(f.lauf_id) + '</td><td>' + standTag(f.entscheidung)
    + '</td><td>' + esc(kurz(f.begruendung) || '–') + '</td></tr>';
  // Seit 23.10.2026 ohne Spalte „wer“: kein Name auf der Übersicht, er steht auf der Gate-2-Seite
  const entschKopf = '<tr><th>Zeit</th><th>Lauf</th><th>Entscheidung</th><th>Begründung</th></tr>';
  const eE = entsch.filter(f => modus[f.lauf_id] === 'echt'), eT = entsch.filter(f => modus[f.lauf_id] !== 'echt');
  B.gate2 = '<section><h2>Entscheidungen an Gate 2</h2>'
    + liste(eE, entschKopf, entschZeile, 5, 'Noch keine Entscheidung zu einem echten Lauf.')
    + (eT.length ? '<details class="mehr"><summary>zu Testläufen (' + eT.length + ')</summary>'
      + liste(eT, entschKopf, entschZeile, 10, '') + '</details>' : '')
    + '</section>';

  // --- An BC4 --------------------------------------------------------------
  // Freigegeben am: Zeitpunkt der Entscheidung an Gate 2, sonst Ende des Laufs
  const freiAm = Object.fromEntries(entsch.filter(f => f.entscheidung === 'freigegeben').map(f => [f.lauf_id, f.zeitpunkt]));
  B.bc4 = '<section><h2>An BC4 weitergegeben</h2>'
    + liste(geliefert, '<tr><th>freigegeben am</th><th>Lieferung</th><th>Lauf</th><th>Konzept</th><th>Epics / Stories</th></tr>',
      l => '<tr><td>' + zeit(freiAm[l.lauf_id] || l.beendet_am) + '</td>'
        + '<td><a href="https://github.com/pg-coe-kmu/coe-factory/pulls?q=' + encodeURIComponent(l.lieferung_id || '')
        + '">' + esc(l.lieferung_id || '–') + '</a></td><td>' + esc(l.lauf_id) + '</td><td>' + esc(konzept(l.konzept_pfad))
        + '</td><td>' + (l.anzahl_epics ?? '–') + ' / ' + (l.anzahl_stories ?? '–') + '</td></tr>',
      5, 'Noch nichts. Testläufe geben nichts an BC4 weiter, erst eine Freigabe im Modus „echt“.')
    + '</section>';

  // P4 (22.10.2026): letzter Lauf des Prüfstands BC3-83
  const P = D.pruefstand;
  const komma = v => v == null ? '–' : Number(v).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const pFaelle = P ? (typeof P.faelle === 'string' ? JSON.parse(P.faelle) : P.faelle || []) : [];
  const auffaellig = pFaelle.filter(f => !f.richtig || f.fundstelle_trifft === false);
  B.pruefstand = '<section><h2>Prüfstand Risikoklasse</h2>'
